import { TimeseriesDatapoint } from '../../../../../core/types/timeseries.js';
import { TimeseriesBandDataPoint } from '../../../../types/timeseries-band.js';

/** Type guard to check whether a value is a number */
export function isBandDataPoint(
  dataPoint: TimeseriesBandDataPoint | TimeseriesDatapoint,
): dataPoint is TimeseriesBandDataPoint {
  return (
    dataPoint !== null &&
    typeof dataPoint === 'object' &&
    'y0' in dataPoint &&
    'y1' in dataPoint
  );
}
